<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\ThemeAssetEnabledVO;

trait ThemeAssetEnabledAccessor
{
    private ?ThemeAssetEnabledVO $_enabled = null;
    public function isEnabled(): ?bool
    {
        return $this->_enabled?->value();
    }
    public function enabled(): ?ThemeAssetEnabledVO
    {
        return $this->_enabled;
    }
    public function isEnabledChanged(?self $original = null): bool
    {
        return null !== $this->_enabled && !$this->_enabled->equals($original?->_enabled);
    }
    public function withEnabled(ThemeAssetEnabledVO|bool|null $enabled): self
    {
        $copy = clone $this;
        $copy->_enabled = ThemeAssetEnabledVO::from($enabled);
        return $copy;
    }
}
